{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SUNBEAM_DB.MAPLEMONK.SUNBEAM_DB_AMAZON_VENDOR_PARTNER_SALES AS SELECT \'AMAZON VC\' AS MARKETPLACE, \'AMAZON VC\' AS CHANNEL, \'AMAZON VC\' AS SOURCE, CONCAT( ASIN, TO_DATE(STARTDATE), ORDEREDUNITS, TRY_TO_DOUBLE(ORDEREDREVENUE:amount::STRING), TO_DATE(ENDDATE) ) AS ORDER_ID, CONCAT( ASIN, TO_DATE(STARTDATE), ORDEREDUNITS, TRY_TO_DOUBLE(ORDEREDREVENUE:amount::STRING), TO_DATE(ENDDATE) ) AS REFERENCE_CODE, CONCAT( ASIN, TO_DATE(STARTDATE), ORDEREDUNITS, TRY_TO_DOUBLE(ORDEREDREVENUE:amount::STRING), TO_DATE(ENDDATE) ) AS SALEORDERITEMCODE, CONCAT( ASIN, TO_DATE(STARTDATE), ORDEREDUNITS, TRY_TO_DOUBLE(ORDEREDREVENUE:amount::STRING), TO_DATE(ENDDATE) ) AS SALES_ORDER_ITEM_ID, ASIN::STRING AS ASIN, STARTDATE::TIMESTAMP AS STARTTIME, ENDDATE::TIMESTAMP AS ENDTIME, ORDEREDUNITS::NUMBER AS ORDERED_UNITS, TRY_TO_DOUBLE(ORDEREDREVENUE:amount::STRING) AS ORDERED_REVENUE, SHIPPEDUNITS::NUMBER AS SHIPPEDUNITS, CUSTOMERRETURNS::NUMBER AS CUSTOMERRETURNS, TRY_TO_DOUBLE(ORDEREDREVENUE:amount::STRING) / NULLIF(ORDEREDUNITS::NUMBER, 0) * CUSTOMERRETURNS::NUMBER AS RETURNED_REVENUE, NULL AS AMAZON_VC_SKU, NULL AS MASTER_SKU, sk.product_name AS PRODUCT_NAME, sk.category AS CATEGORY, NULL AS BRAND, NULL AS PRODUCT, NULL AS PACK_TYPE, NULL as mapped_product_name, NULL as mapped_category, NULL as mapped_sub_category, sk.sku_code as commonsku, NULL as bucket_1, NULL as bucket_2, NULL as sku_mrp FROM SUNBEAM_DB.MAPLEMONK.SUNBEAM_AmazonVC_GET_VENDOR_SALES_REPORT FI LEFT JOIN ( SELECT * FROM SUNBEAM_DB.MAPLEMONK.SUNBEAM_SKU_MASTER WHERE FINAL_MARKETPLACE LIKE \'%AMAZON%\' QUALIFY ROW_NUMBER() OVER ( PARTITION BY TRIM(UPPER(PRODUCT_ID)) ORDER BY SKU_CODE ) = 1 ) SK ON TRIM(UPPER(SK.PRODUCT_ID)) = TRIM(UPPER(FI.ASIN)) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SUNBEAM_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            